package com.example

import com.example.ExamQuestionHelper.QSpec

object MusicLiveExamFolkSongsBank2 {
    private const val T = "ශ්‍රී ලාංකේය ජන සංගීතය හා ජන ගී"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ගැමි ජනයා විසින් නිර්මාණය කළ ජන ගීවල නිශ්චිත කර්තෘවරයෙකු සඳහන් නොවීමට හේතුව කුමක්ද?", "ඒවා මුඛ පරම්පරාගතව පොදු ජන සමාජය තුළින් බිහිවූ බැවින්", "රජතුමා විසින් කතුවරුන්ගේ නම් තහනම් කළ බැවින්", "ඒවා විදේශීය පොත්වලින් පිටපත් කළ බැවින්", "ඒවා ගායනා කිරීමට එක් අයෙකුට පමණක් අයිති වූ බැවින්", "ජන කවි යනු මුඛ පරම්පරාවෙන් පරපුරෙන් පරපුරට සංස්කරණය වෙමින් ආ සාමූහික නිර්මාණ වේ."),
        q("කරත්ත කවි ගායනයේදී ගායකයා කවියේ අගට 'ඒ... ඉ...' යනුවෙන් ස්වර ඇදීමෙන් ප්‍රකාශ වන හැඟීම කුමක්ද?", "විඩාව, තනිකම සහ දුර ගමනේ අපහසුතාව", "තරගකාරී යුද උද්‍යෝගය", "වේගවත් නර්තන ප්‍රීතිය", "රාජ සභාවේ ගෞරවය", "රාත්‍රී අඳුරු මාවත්වල ගවයින් දක්කන විට ඇතිවන ශෝකී හැඟීම එයින් මතු වේ."),
        q("'සක්වල ගලක් වාගෙයි මට ගාල දැකලා' යන පද්‍ය කොටසේ 'ගාල' යනුවෙන් අදහස් කෙරෙන්නේ කුමක්ද?", "ගවයින් ලිහා දමා කරත්ත නවතා විවේක ගන්නා ස්ථානය", "වෙරළ තීරයේ ධීවර වරාය", "කඳු මුදුනේ බම්බර වදය", "රජ මාලිගාවේ කවිකාර මඩුව", "දිගු ගමන්වලදී කරත්ත ගාල් කළ නවාතැන් ස්ථාන ගාල ලෙස හැඳින්විණි."),
        q("පාරු කවි ගායනය සිදු කරන අවස්ථාවේදී පාරුවේ ගමන් දිශාව හා වේගය අනුව ගීතයේ කුමක් වෙනස් වේද?", "තාල හා හුස්ම ඇදීමේ ප්‍රමාණය", "රාගයේ ථාට සංඛ්‍යාව", "තබ්ලාවේ ඨේකාව", "ස්ටාෆ් රේඛා සංඛ්‍යාව", "උඩු ගං බලා රිට ගසන විටදී සහ පහළ ගං බලා යන විටදී ගායන රටාව වෙනස් වේ."),
        q("උඩරට, පහතරට සහ සබරගමු යන ප්‍රදේශ තුනෙන්ම හමුවන දේශීය ශාන්තිකර්ම ගායනා සාමාන්‍යයෙන් හඳුන්වන්නේ කුමන නමින්ද?", "යාතිකා, කන්නලව් සහ ස්තෝත්‍ර කවි", "ඛයාල් සහ ධමාර්", "පැල් හා පතල් කවි", "කපිරිඤ්ඤා ගී", "දේවාශිර්වාදය පතා ගැයෙන යාතිකා හා කන්නලව් ශාන්තිකර්ම සංගීතයේ ප්‍රධාන අංගයකි."),
        q("සිංහල දේව කන්නලව් හා යාතිකා ගායනයේදී බහුලව පසුබිමින් වැයෙන වාද්‍ය භාණ්ඩය කුමක්ද?", "යක්බෙරය, ගැටබෙරය හෝ දවුල", "සිතාරය", "බන්සූරිය", "හාමෝනියමය", "ශාන්තිකර්මවලදී අදාළ සම්ප්‍රදායේ මංගල බෙරය කන්නලව්ව සමඟ වැයේ."),
        q("ලංකාවේ 'රොඩී' ජන කොටස හෝ ගැමි කාන්තාවන් විසින් විශේෂයෙන් කරකවමින් වාදනය කර ගැයූ වාද්‍ය භාණ්ඩය කුමක්ද?", "අත් රබාන (විරිඳු රබාන)", "පඛාවජය", "ජල්තරංග", "සන්තූරය", "රබන් කරකැවීම සහ අත් රබන් ගසමින් ගැයීම දේශීය ජන කලාවේ අංගයකි."),
        q("'විරිඳු' ගායනා සම්ප්‍රදායේ ඇති සුවිශේෂී කලාත්මක දක්ෂතාවය කුමක්ද?", "ක්ෂණිකව සිතා පද බඳිමින් අත් රබාන වයා තාලයට ගැයීම", "පැරණි ලිඛිත පොත් කියවමින් නැටීම", "වේදිකාවේ තිර රෙදි පිටුපස සිට ගැයීම", "තබ්ලාවෙන් චෞගුන් පමණක් වැයීම", "විරිඳු කවි ක්ෂණික කාව්‍ය නිර්මාණ ශක්තිය හා රබන් වාදනය එක් කළ ජන කලාවකි."),
        q("පැරණි ගැමි සමාජයේ දිගු රාත්‍රීන්හි පැල්පත් තුළ දරුවන්ට සදාචාරය හා ධර්මය ඉගැන්වීමට ගැයූ ගීත මොනවාද?", "පූජා කාව්‍ය, තුන් සරණය සහ ජාතක කවි", "කපිරිඤ්ඤා ගීත", "නාඩගම් දෙබස්", "හෝලි ධමාර් ගී", "බෞද්ධ සංස්කෘතිය ඇසුරින් ගොඩනැගුණු තුන් සරණය ආදිය ජනප්‍රිය විය."),
        q("'බුද්ධං සරණේ සිරස දරාගෙන' යන ප්‍රකට කවිය අයත් වන්නේ කුමන ජන ගී ගණයටද?", "තුන් සරණය කවි", "පතල් කවි", "පාරු කවි", "බම්බර කවි", "ශ්‍රී පාද වන්දනා ගමන්වලදී බැතිමතුන් විසින් තුන් සරණය කවි සමූහ වශයෙන් ගයති."),
        q("ශ්‍රී පාද වන්දනාවේ යන බැතිමතුන් කන්ද නැඟීමේ වෙහෙස නිවා ගැනීමට ගැයූ කවි මොනවාද?", "තුන් සරණය හා සමන්තකූට වන්දනා කවි", "කරත්ත කවි", "පතල් කවි", "රබන් පද", "සිරිපා කරුණා කිරීමේදී ගමන් කවි ලෙස තුන් සරණය ගායනා කෙරේ."),
        q("සිංහල වන්නම් දහඅට අතුරින් 'ඇතාගේ ගමන් විලාසය' නිරූපණය කරන වන්නම කුමක්ද?", "ගජගා වන්නම", "තුරඟා වන්නම", "මයුරා වන්නම", "හනුමා වන්නම", "මේඝ රජුගේ ඇතා වන ඓරාවණයාගේ ගමන ගජගා වන්නමෙන් නිරූපිතය."),
        q("වන්නම් දහඅට අතරින් 'අශ්වයාගේ ගමන' නිරූපණය කෙරෙන වන්නම කුමක්ද?", "තුරඟා වන්නම", "සිංහරාජ වන්නම", "උරගා වන්නම", "මූසලඩි වන්නම", "සිදුහත් කුමරු කන්ථක අසු පිට නැඟී ගිය ගමන තුරඟා වන්නමේ තේමාවයි."),
        q("සිංහල වන්නම් අතරින් 'මොනරාගේ රංගනය' වර්ණනා කර ගයන වන්නම කුමක්ද?", "මයුරා වන්නම", "උකුසා වන්නම", "කිරලා වන්නම", "හංස වන්නම", "කතරගම දෙවියන්ගේ වාහනය වන මොනරාගේ රංගන විලාසය මයුරා වන්නමයි."),
        q("ගොයම් නෙළීමේදී ගැයෙන 'නෙළුම් කවි' වල අවසානයට යෙදෙන විශේෂ ලාලිත්‍යමය ලක්ෂණය කුමක්ද?", "හඬ මඳක් කම්පනය කරමින් සුමට ලෙස ස්වරය අවසන් කිරීම", "තබ්ලාවෙන් තිහායි කොටසක් ගැසීම", "අධික ශබ්දයෙන් කෑගසා නැවතීම", "විකෘති ස්වර පහම ගැයීම", "නෙළුම් කවිවල ස්වර ඇදීම හා කෙළවර නැමීම ඉතා සියුම්ය."),
        q("ජන ගී ආශ්‍රයෙන් ස්වර පරීක්ෂා කිරීමේදී බොහෝ දේශීය ජන ගීවල පොදුවේ දැකිය හැකි මූලික ස්වර පරාසය කුමක්ද?", "ස, රි, ග, ම හෝ ප, ධ, නි, සඃ වැනි පටු ස්වර කලාපය", "මන්ද්‍ර ප සිට තාර ප දක්වා දැවැන්ත ස්වර පරාසය", "තීව්‍ර මධ්‍යමය මත පදනම් වූ කල්‍යාණ් ස්වර පරාසය", "කෝමල රි හා තීව්‍ර ම සහිත පූර්වි පරාසය", "ගැමි ගීත පොදු ජනයාට පහසුවෙන් ගැයිය හැකි සීමිත ස්වර 3–4ක් වටා ගෙතේ."),
        q("ලයනල් රංවල සහ රෝහණ බැද්දගේ වැනි කලාකරුවන් ශ්‍රී ලාංකේය සංගීතයට සිදු කළ ප්‍රධාන මෙහෙවර කුමක්ද?", "ශ්‍රී ලාංකේය ජන ගී සහ ජන නාද රටා නූතන වේදිකාව තුළ සංරක්ෂණය කර ජනප්‍රිය කිරීම", "බටහිර ඔපෙරා ගීත සිංහලට පරිවර්තනය කිරීම පමණක්", "කර්ණාටක මේලකර්තා 72 මෙරට පාසල්වලට හඳුන්වා දීම", "පෘතුගීසි කපිරිඤ්ඤා ගීත තහනම් කිරීම", "ගැමි ගීත නව ප්‍රසංග හා මාධ්‍ය ඔස්සේ ජනගත කිරීම ඔවුන්ගේ සේවාවයි."),
        q("ශ්‍රී ලංකාවේ ජන කවියක පද ගායනා කරන විට ඒවායෙහි 'ලිඛිත රාග නියමයක්' නොතිබුණද ඒවා මධුර වන්නේ ඇයි?", "ස්වාභාවික මානව හැඟීම් හා භාෂා ශබ්ද රටා මත පදනම්ව ගැයෙන නිසා", "සෑම ජන කවියකම භාත්ඛණ්ඩේ ස්වරලිපි ලියා ඇති නිසා", "කෝමල ස්වර හතරම අනිවාර්යයෙන් යොදන නිසා", "එකම ත්‍රිතාල බෝල් පෙළ භාවිත කරන නිසා", "ජන ජීවිතයේ අත්දැකීම්වලින් උපන් ස්වාභාවික මිහිරියාවක් ඒවායේ ඇත."),
        q("වන්නමක 'කස්තිරම' වාදනය කිරීමෙන් පසුව නැට්ටුවා සහ ගායකයා ඉදිරිපත් කරන කෙටි අවසන් නැටුම් කොටස කුමක්ද?", "අඩව්ව (සහ සීරුමාරුව)", "තානම", "අලාපය", "පේෂ්කාරය", "තානම, කවිය, මාත්‍රාව, කස්තිරම, සීරුමාරුව හා අඩව්ව වන්නමක අංග වේ."),
        q("'දළු මුර උපත' හෝ 'කොහොඹා කංකාරිය' වැනි ශාන්තිකර්මවල ගැයෙන කවි වර්ගය හඳුන්වන්නේ කුමන නමින්ද?", "යාග කවි (උපත් කවි / ශාන්තිකර්ම ගී)", "කරත්ත කවි", "පතල් කවි", "ඔන්චිලි වාරම්", "දෙවියන් හා වස්තූන්ගේ උපත කියැවෙන උපත් කවි ශාන්තිකර්මවල ගැයේ."),
        q("සිංහල ගැමි කාන්තාවන් 'මෝල් ගස්' භාවිතයෙන් වී කෙටීමේදී තාලයට එක්ව ගයන ලද ජන ගී මොනවාද?", "වංගෙඩි හෝ වී කෙටීමේ කවි", "පාරු කවි", "බම්බර කවි", "පැල් කවි", "මෝල් ගස් වංගෙඩියට වැටෙන හඬ අනුකරණය කරමින් තාලයට ගී ගැයූහ."),
        q("දේශීය ජන ගී සමූහය අතරින් 'සුළඟට හා රැළිවලට' වඩාත් සමීප නිදහස් තාලයක් පවතින ජන ගී කවරේද?", "පාරු කවි", "රබන් පද", "ලී කෙළි ගී", "කළගෙඩි ගී", "ජල ප්‍රවාහය සමඟ නිදහසේ පාවී යන රිද්මයක් පාරු කවිවල පවතී."),
        q("කරත්ත කවිවලින් ගවයා කෙරෙහි ගොවියා දැක්වූ කුමන ආකල්පය මනාව ප්‍රකට වේද?", "මෛත්‍රිය, අනුකම්පාව හා කෘතවේදීත්වය", "කෝපය සහ ක්‍රෝධය", "නොසැලකිල්ල", "විනෝද ක්‍රීඩාවක් ලෙස සැලකීම", "'මමත් ඉපදුණොත් ගවයෙකු වී මෙහෙම' වැනි පද කරුණාව පෙන්වයි."),
        q("උඩරට නැටුම් කලාවට සම්බන්ධ 'තාලම්පට' වාදනය කරන්නේ ගායනයේ කුමන අවශ්‍යතාව සපුරාලීමටද?", "තාලයේ සම හා මාත්‍රා ඒකාකාරව නියම කිරීමට", "රාගයේ ස්වර 7 නිපදවීමට", "කටහඬ වසා දැමීමට", "විලම්බිත අලාපයක් ඇරඹීමට", "තියුණු ලෝහ ශබ්දය මඟින් ගායනයේ හා බෙරයේ තාලය ස්ථිරව පවත්වා ගනී."),
        q("දේශීය ජන සංගීතයේදී 'පහතරට' ශාන්තිකර්ම ගායනා සඳහා විශේෂ වූ තාල ව්‍යුහයන් හඳුන්වන්නේ කෙසේද?", "පහතරට තාල වට්ටම් (උදා මැදුම් තනි තිත, සුලු තිත)", "උත්තර භාරතීය ත්‍රිතාලය", "බටහිර 3/4 වෝල්ට්ස් තාලය", "මෝගල් ධමාර් තාලය", "දෙතිත, තුන්තිත, සිව්තිත වැනි දේශීය තිත් ක්‍රම භාවිත කෙරේ."),
        q("දේශීය සංගීතයේදී 'තිත' යන වචනයෙන් අදහස් කෙරෙන්නේ කුමක්ද?", "සාම්ප්‍රදායික බෙර හා වන්නම් තාලයේ මූලික කාල ඒකකය හා පහර", "ස්වරය මත තබන තාර සලකුණ", "සිතාරයේ පිත්තල පර්දාව", "තබ්ලාවේ කළු තට්ටුව", "උඩරට හා පහතරට සංගීතයේ දෙතිත, මැදුම් දෙතිත ආදී ලෙස තිත් ක්‍රම ඇත."),
        q("වන්නම් ගායනයේදී 'මැදුම් දෙතිත', 'සුළු දෙතිත', 'තනි තිත' යනුවෙන් හඳුන්වන්නේ මොනවාද?", "දේශීය තාල වර්ගීකරණයන්", "භාරතීය රාග වර්ග", "සිතාරයේ තන්තු වර්ග", "බටහිර ක්ලෙෆ් සලකුණු", "සිංහල නර්තන හා වන්නම් කවි මෙම දේශීය තිත් තාල අනුව ගැයේ."),
        q("ගජගා වන්නම ගායනා කරනු ලබන සාම්ප්‍රදායික දේශීය තාලය කුමක්ද?", "මැදුම් මහා දෙතිත (සතර මාත්‍රා)", "රූපක් තාලය", "ධමාර් තාලය", "තීව්‍රා තාලය", "මන්දගාමී හා ගාම්භීර ඇත් ගමන මැදුම් දෙතිත තාලයෙන් නිරූපිතය."),
        q("'සැවුලා වන්නම', 'හනුමා වන්නම' සහ 'වෛරෝඩි වන්නම' අයත් වන්නේ කුමන දේශීය කලා සම්ප්‍රදායටද?", "උඩරට දහඅට වන්නම් සම්ප්‍රදායට", "පහතරට සන්නි යකුමට", "නූර්ති නාට්‍ය ගී සම්ප්‍රදායට", "බයිලා කපිරිඤ්ඤා කලාවට", "මහනුවර යුගයේ රචිත සම්භාව්‍ය දහඅට වන්නමේ ප්‍රකට අංග මේවා වේ."),
        q("දේශීය සරල ගී නිර්මාණයේදී ආචාර්ය ඩබ්ලිව්. ඩී. අමරදේවයන් ගැමි නාද රටා යොදාගත් අයුරු කෙබඳුද?", "ජන ගීයේ මූලික නාද හරය හා උත්තර භාරතීය ස්වර ශිල්පය සුසංයෝග කිරීම", "ජන ගී සම්පූර්ණයෙන් අත්හැර බටහිර සංගීතය පමණක් ගැනීම", "වචන වෙනුවට බෙර පද පමණක් ගැයීම", "පැරණි කවි වෙනස් නොකර එලෙසම තබ්ලාවෙන් පමණක් ගැයීම", "'වන්නම් තනු' හා 'පැල් කවි' රටා අමරදේවයන්ගේ ගීතවල නව ජීවයක් ලැබීය."),
        q("පැරණි සිංහල ජන කවිවල භාෂාවේ 'එළිසමය' රැකීමෙන් ගායනයට ලැබෙන ප්‍රධාන වාසිය කුමක්ද?", "මතක තබා ගැනීමේ පහසුව සහ ශ්‍රව්‍ය රිද්ම මාධුර්යය", "වාද්‍ය භාණ්ඩයක සංඛ්‍යාතය වෙනස් වීම", "කෝමල ස්වර ශුද්ධ බවට පත්වීම", "තාලයේ මාත්‍රා 16ක් නිර්මාණය වීම", "පේළි හතරේ අග අකුරු හෝ ශබ්ද ගැළපීම ගැමි කවි මිහිරි කරයි."),
        q("ගොයම් කැපීමේදී ගැමියන් 'අද මෙතන සිටිනා - අපේ මේ සොඳුරු අයියණ්ඩි' ආදී ලෙස සමූහව ගැයීමෙන් වන්නේ කුමක්ද?", "සාමූහික එකමුතුකම වර්ධනය වී වැඩ කිරීමේ වෙහෙස දුරු වීම", "එකිනෙකා අතර තරගකාරී ගැටුම් ඇති වීම", "කුඹුරේ වැඩ ප්‍රමාද වීම", "පැල් කවි අමතක වීම", "ජන ගී සාමූහික ගැමි ජීවිතයේ සමාජ බැඳීම ශක්තිමත් කළේය."),
        q("ශ්‍රී ලංකාවේ ප්‍රාදේශීය ජන ගී අතර 'මොණරාගල හා ඌව වෙල්ලස්ස' ප්‍රදේශවල විශේෂයෙන් ප්‍රචලිත වූ කවි මොනවාද?", "පැල් කවි සහ බම්බර කවි", "නැව් හා මුහුදු කවි පමණක්", "කපිරිඤ්ඤා ගී පමණක්", "පෝතුගීසි කන්තාරු", "කඳු හා වනාන්තර ආශ්‍රිත ගොවිතැන් ජීවිතය නිසා පැල් හා බම්බර කවි එහි බහුලය."),
        q("දකුණු ලංකාවේ හා සබරගමුවේ 'රත්නපුර' ප්‍රදේශය ආශ්‍රිතව බිහි වූ සුවිශේෂී ජන ගී කාණ්ඩය කුමක්ද?", "පතල් කවි", "මුහුදු මාදැල් කවි", "කපිරිඤ්ඤා ගී", "කවිකාර මඩු ප්‍රශස්ති", "මැණික් පතල් කර්මාන්තය නිසා සබරගමුවේ පතල් කවි ඉතා ජනප්‍රිය විය."),
        q("සිංහල ජන සංගීතයේදී 'තොටිලි ගී' හෙවත් දරු නැළවිලිවල අන්තර්ගත වන මූලික භාවය කුමක්ද?", "මව් සෙනෙහස හා ශාන්ත වාත්සල්‍ය භාවය", "රෞද්‍ර හා වීර භාවය", "හාස්‍ය හා කෝපය", "විරහ දුක පමණක්", "මෘදු ලාලිත්‍යයෙන් දරුවා නින්දට පත් කිරීම මෙහි අරමුණයි."),
        q("පැරණි ජන කවි සංරක්ෂණය කිරීමේදී වත්මන් පරපුර මුහුණ දෙන ප්‍රධාන අභියෝගය කුමක්ද?", "යාන්ත්‍රික කෘෂිකර්මය නිසා සාම්ප්‍රදායික ශ්‍රම ගී භාවිතයෙන් ඈත් වීම", "ජන කවිවලට ස්වර නොමැති වීම", "සිංහල භාෂාවේ අක්ෂර මදි වීම", "පාසල් විෂය මාලාවෙන් සංගීතය ඉවත් කිරීම", "ජන ජීවිතයේ නවීකරණය සමඟ සජීවී ජන ගී ගායනා අවස්ථා අඩු වී ඇත."),
        q("දේශීය ජන ගී ගායනය හා උත්තර භාරතීය රාගධාරී ගායනය සැසඳීමේදී පැහැදිලි වන වෙනස කුමක්ද?", "ජන ගී සරල ස්වර 3–4ක සහ අනියත රිද්මයක ඇති අතර රාග ගායනය ව්‍යාකරණානුකූල ස්වර 5–7ක පවතී", "ජන ගී සැමවිටම සංස්කෘත භාෂාවෙන් ලියා ඇති අතර රාග සිංහලෙන් ලියා ඇත", "රාග ගායනයේ තාල නැති අතර ජන ගීවල ත්‍රිතාලය පමණක් ඇත", "ජන ගී ගායනයට තම්බුරාව අනිවාර්ය වන අතර රාගවලට ගැටබෙරය වයයි", "ජන ගී නිදහස් හැඟීම් ප්‍රකාශනයක් වන අතර රාග ශාස්ත්‍රීය නීති පද්ධතියකි."),
        q("'සී. ද එස්. කුලතිලක' මහතාගේ ජන සංගීත පර්යේෂණ අනුව සිංහල ජන කවිවල බහුලව යෙදෙන ස්වර සංගතිය කුමක්ද?", "ස, රි, ග, ම හෝ ග, ම, ප ස්වර ආශ්‍රිත නාද රටා", "තීව්‍ර මධ්‍යමය සමඟ කෝමල රි-ධ රටා", "මාරවා හා පූර්වි ථාටවල ස්වර", "චෞතාලයට බැඳුණු පඛාවජ් බෝල්", "ගැමි කවිවල නාද රටා සරල පූර්වාංග ස්වර තුළ රැඳී ඇති බව එතුමා පෙන්වා දුන්නේය."),
        q("පහත දැක්වෙන අවස්ථා අතුරින් 'ඔන්චිලි වාරම්' ගායනා කරන උත්සව සමය කුමක්ද?", "බක් මහ හෙවත් සිංහල හා දෙමළ අලුත් අවුරුදු සමය", "ඇසළ පොහොය හා වස් කාලය", "නත්තල් උත්සව සමය", "වෙසක් පෙරහැර සමය", "අවුරුදු ක්‍රීඩාවක් ලෙස ඔන්චිලි පැදීමේදී වාරම් කවි ගැයේ."),
        q("කරත්ත කවි හා පැල් කවි යන දෙකම සමාන වන්නේ කුමන අංශයකින්ද?", "දෙකම ශ්‍රමයේ වෙහෙස හා තනිකම මකා ගැනීමට ගැයූ නිදහස් නාද කවි වීම", "දෙකම රජ මාලිගයේ කවිකාර මඩුවේදී රචනා වීම", "දෙකම වේදිකා නාට්‍ය සඳහා නිපදවීම", "දෙකම මාත්‍රා 16 ත්‍රිතාලයට වාදනය කිරීම", "හුදෙකලා ශ්‍රම පරිසරයන්හිදී සිතට සහනය ගෙන දීමට මේවා ගැයුණි."),
        q("ගොයම් කවි හා නෙළුම් කවි අතර ඇති පොදු ලක්ෂණය කුමක්ද?", "දෙකම වී ගොවිතැන හා සාමූහික ශ්‍රමය සමඟ බැඳී පැවතීම", "දෙකම ගංගාවල පාරු පැදීමේදී ගැයීම", "දෙකම පතල් තුළ ගැයීම", "දෙකම බටහිර වාද්‍ය වෘන්දවල ගැයීම", "ශ්‍රී ලාංකික කෘෂිකාර්මික සංස්කෘතියෙන් බිහිවූ සාමූහික කවි විශේෂ දෙකකි."),
        q("කුඩා දරුවෙකුගේ ක්‍රීඩා හා විනෝදය වෙනුවෙන් ගැයෙන 'කවට කවි' හෝ 'තේරවිලි කවි' අයත් වන්නේ කුමන සංගීත කොටසටද?", "දේශීය ජන ගී සාහිත්‍යයට", "ධෲපද් ශාස්ත්‍රීය සංගීතයට", "නාඩගම් රංග ශෛලියට", "බටහිර ඔපෙරා ගායනයට", "ළමා ජන ගී හා තේරවිලි කවි ගැමි විනෝද සංස්කෘතියේ කොටසකි."),
        q("'මංගල අෂ්ටක' සහ 'ජයමංගල ගාථා' වලට ශ්‍රී ලාංකේය සමාජයේ හිමි වී ඇති සංගීතමය තත්ත්වය කුමක්ද?", "සාම්ප්‍රදායික චාරිත්‍ර හා සුබ කටයුතුවල ආශිර්වාද ගායනා ලෙස", "රණශූර යුද පෙරමුණේ ගයන ගී ලෙස", "පතල් හා බම්බර කවි වෙනුවට ගයන ගී ලෙස", "රබන් නැටුම් සඳහා පමණක් ගයන පද ලෙස", "මංගල අවස්ථාවල සුබ පැතීම සඳහා මෙම සාම්ප්‍රදායික ගායනා යොදා ගැනේ."),
        q("දේශීය ජන ගීයක 'සම්ප්‍රදායික නාදය' ආරක්ෂා කිරීම සඳහා නව පරපුර විසින් ප්‍රගුණ කළ යුත්තේ කුමක්ද?", "ප්‍රාදේශීය උච්චාරණය, හුස්ම ඇදීම හා ගැමි හඬ හැසිරවීම", "බටහිර ඉලෙක්ට්‍රොනික තාල යන්ත්‍ර පමණක් යෙදීම", "කවි පද ඉංග්‍රීසි භාෂාවට හැරවීම", "රාගවල වර්ජිත ස්වර වැඩි කිරීම", "මුල් ගැමි ගායන රටාව හඳුනාගෙන එහි ජීව ගුණය රැකීම වැදගත්ය."),
        q("ශ්‍රී ලංකාවේ 'ගැමි කවි' ගායනා කරන විට හුස්ම රඳවා ගැනීමට අමතරව ගායකයා කටහඬ හසුරුවන සුවිශේෂී රටාව කුමක්ද?", "කටහඬේ ස්වාභාවික ඇදීම් හා ලයාන්විත නැමීම්", "ඉතා කෙටි හා තද බෙර පහර වැනි කඩතොළු ශබ්ද", "එකම ස්වරයක කිසිදු චලනයක් නැතිව සිටීම", "රාග අලාප මෙන් විනාඩි 30ක් පමණ ඇදීම", "සිංහල ජන කවිවලට ආවේණික මෘදු ඇදීම් හා ස්වර දෝලන එහි මිහිරියාව දේ."),
        q("සිංහල ජන කවියේ 'වෘත්ත ඡන්දස්' අතර වඩාත් බහුලව යෙදෙන කාව්‍ය රීතිය කුමක්ද?", "සිව්පද (පාද 4) ඡන්දස්", "සංස්කෘත මන්දාක්‍රාන්තා වෘත්තය", "ඉංග්‍රීසි සොනට් ක්‍රමය", "ජපන් හයිකු ක්‍රමය", "ජන කවි බොහොමයක් පාද හතරක සමුද්‍රඝෝෂ හෝ සැහැලි විරිතට ගැයෙන සිව්පද වේ."),
        q("'සමුද්‍රඝෝෂ විරිත' අනුව බහුලව ගායනා කෙරෙන දේශීය කවි විශේෂය කුමක්ද?", "පැල් කවි, පාරු කවි හා කරත්ත කවි", "ලී කෙළි කවි පමණක්", "කපිරිඤ්ඤා ගීත", "නූර්ති ඛ්‍යාල් ගීත", "මාත්‍රා 18 සමුද්‍රඝෝෂ විරිත බොහෝ සිංහල ශ්‍රම කවිවල පදනමයි."),
        q("සිංහල 'නාඩි' හෙවත් 'තාලම' මගින් ජන කවි හා වන්නම්වලදී රැකගන්නේ කුමක්ද?", "පද අතර නිවැරදි කාල පරතරය හා ලය", "ස්වරයේ ශ්‍රැති සංඛ්‍යාතය පමණක්", "භාණ්ඩයේ දැව වර්ගය", "ගායකයාගේ උස", "ජන කවියේ ගලා යෑම හා වන්නම්වල නර්තන පියවර තිත හෙවත් තාලය මත පදනම් වේ."),
        q("උඩරට දහඅට වන්නම්වල එන 'වෛරෝඩි වන්නම' මගින් නිරූපණය කෙරෙනුයේ කවර වස්තුවක්ද?", "මැණික් ගලේ (වෛරෝඩි මාණික්‍යයේ) දීප්තිය හා ශිව දේව කතාව", "මී මැස්සන්ගේ පියාසැරිය", "ගැල් කරත්තයේ ගමන", "පතල් කැණීම", "වටිනා මැණිකක ආලෝකය හා දිස්නය උපමා කර ගනිමින් වෛරෝඩි වන්නම රචනා වී ඇත."),
        q("'නෛයඩි වන්නම' සඳහා පාදක වී ඇති කතා පුවත කුමන බෞද්ධ ජාතක කතාවද?", "භූරිදත්ත ජාතකය (නාග ලෝකයේ නාග රාජයා)", "වෙස්සන්තර ජාතකය", "සඳකිඳුරු ජාතකය", "උම්මග්ග ජාතකය", "බෝසතාණන් වහන්සේ භූරිදත්ත නාගරාජව සිටි කතාව ඇසුරෙන් නෛයඩි වන්නම නිර්මාණය විය."),
        q("'කුදිරඩි වන්නම' හෙවත් දෙමළ ආභාසිත වන්නමක් නොවන 'මුසලඩි වන්නමෙන්' පෙන්වන්නේ කුමන සතෙකුගේ චලනයද?", "හාවාගේ පැන යෑම හා චලනය", "ඇතුගේ ගමන", "මොනරාගේ නැටුම", "සිංහයාගේ ගර්ජනාව", "බියපත් වී පනින හාවෙකුගේ (මුසල) ගමන් රටාව අනුව මුසලඩි වන්නම රචනා කර ඇත."),
        q("'සැවුලා වන්නම' මගින් කුකුළාගේ කවර ලක්ෂණයක් හා කතාවක් ගායනා කෙරේද?", "අරුණෝදයේ කුකුළා හැඬලීම හා කතරගම කොඩිය", "සිංහයාගේ වනයේ දඩයම් ගමන", "ගොයම් කපා කමතේ ගොඩගැසීම", "ගඟේ පාරු පැදීමේ වෙහෙස", "උදෑසන සැවුළා හඬලන විලාසය හා ස්කන්ධ කුමාර සටන පිළිබඳව සැවුලා වන්නමේ එයි."),
        q("'හංසා වන්නම' ගායනා කිරීමේදී ගායකයා හා නැට්ටුවා මවන දෘශ්‍ය හා ශ්‍රව්‍ය රසය කුමක්ද?", "දියේ පිහිනන හංසයාගේ සුමුදු ලාලිත්‍යමය ගමන", "වඳුරාගේ කඩිසර පැනීම", "කුරහන් ඇඹරීම", "යුද පිටියේ ඝෝෂාව", "හංසයාගේ සන්සුන් හා අලංකාර ජල ක්‍රීඩා විලාසය මෙහි නාද රටාවෙන් දිස්වේ."),
        q("'සිංහරාජ වන්නම' ගායනයේදී යොදාගන්නා තාල හා හඬ හැසිරවීම කවර ගුණාංගයක් ඉස්මතු කරයිද?", "වනයේ රජු වූ සිංහයාගේ තේජස හා වීර රසය", "හාවාගේ බියගුලු බව", "දරුවෙකුගේ නින්ද", "කළගෙඩි ක්‍රීඩාව", "ගාම්භීර වීර රසය හා එඩිතර බව සිංහරාජ වන්නමේ කැපී පෙනේ."),
        q("'අසුර වන්නම' සහ 'සුරපති වන්නම' මගින් සිහිපත් කෙරෙන තේමාව කුමක්ද?", "දේව - අසුර සංග්‍රාමය හා ඉන්ද්‍ර දෙවි තේජස", "හේන් ගොවිතැනේ කුරහන් කැපීම", "මුහුදේ දැල් එළා මසුන් ඇල්ලීම", "රාත්‍රී පැල් රැකීමේ අත්දැකීම්", "දෙවිවරුන්ගේ හා සුරපතිගේ මහිමය පුරාණ කතා ඇසුරින් මෙම වන්නම්වල වර්ණනා කෙරේ."),
        q("'ගහක වන්නම' (ගාහක වන්නම) යනුවෙන් දහඅට වන්නමේ හඳුන්වනු ලබන්නේ කුමක් වර්ණනා කරන වන්නමද?", "ශංඛය හෙවත් දකුණු අත හක්ගෙඩියේ මංගල නාදය", "මහා වනාන්තරයේ ගස් වැල්", "ගොයම් පැළ", "කුරහන් ගල", "සක්‍ර දෙවියන්ගේ විජයෝත්තර හක්ගෙඩියේ නාදය හා මහිමය ගාහක වන්නමේ කියැවේ."),
        q("ශ්‍රී ලංකාවේ 'ගැමි නැටුම්' හා 'ජන ගී' අතර පවතින 'තාලම් කවි' වල ප්‍රධාන කාර්යය කුමක්ද?", "නැට්ටුවන්ගේ පියවර තැබීමට ස්ථිර තාල හා රිද්ම සැපයීම", "රාත්‍රී නින්දට පත් කිරීම", "බෙර හඬ නතර කිරීම", "කවි පොත් විකිණීම", "ලී කෙළි, පන්තේරු හා කළගෙඩි නැටුම්වලදී කවි තාලය නැටුම මෙහෙයවයි."),
        q("දකුණු ලංකාවේ ප්‍රචලිත 'මාතර කවි' හා 'සීපද' තුළ දක්නට ලැබෙන විශේෂ ලක්ෂණය කුමක්ද?", "සාහිත්‍යමය ඔපමට්ටම් වූ මිහිරි වචන හා එළිසමය", "සංස්කෘත ව්‍යාකරණ පමණක් තිබීම", "ඉංග්‍රීසි පද මිශ්‍ර වීම", "තාල රහිත ගද්‍ය පාඨ වීම", "ගජමන් නෝනා, කරතොට හිමි ආදී මාතර කවි පරපුරේ ආභාසය ගැමි කවිවලටද ලැබිණි."),
        q("ඌව වෙල්ලස්ස හා බින්තැන්න ප්‍රදේශයේ 'වැදි ජනතාවගේ' ජන ගීවල ඇති ප්‍රධාන ස්වර ලක්ෂණය කුමක්ද?", "ඉතා සීමිත ස්වර දෙක තුනක් තුළ දිවෙන ආදිවාසී නාද රටා", "සප්ත ස්වර හතම කෝමල හා තීව්‍ර වීම", "තබ්ලා තේකා භාවිතය", "පියානෝ සංගීතය", "සාම්ප්‍රදායික වැදි ගීත සරල ස්වර පරාසයක හා පුනරුච්චාරණ රිද්මයකින් ගැයේ."),
        q("දේශීය ජන ගීවල 'තුන් සරණය' ගායනා කරනු ලබන්නේ කවර පූජනීය අවස්ථාවකද?", "බෞද්ධ වන්දනා ගමන්වලදී (උදා. සිරිපා කරුණාව)", "මුහුදු යාත්‍රා යුද්ධවලදී", "කපිරිඤ්ඤා සාදවලදී", "ගෙවල් සෑදීමේදී පමණක්", "ශ්‍රී පාද වන්දනාවේ යන බැතිමතුන් බුද්ධ, ධම්ම, සංඝ ගුණ සිහිකරමින් තුන් සරණය ගයති."),
        q("සිරිපා කරුණා කිරීමේදී ගැමියන් එක්ව ගායනා කරන 'සිරිපා කවිවල' අවසානයට කියන ආශිර්වාද කොටස කුමක්ද?", "සාධුකාර හා සමන් දෙවිඳු කරුණාවයි පාඨය", "විනෝදාත්මක උපහාස කවි පද", "රබන් කැරකැවීමේ වේගවත් පද", "කපිරිඤ්ඤා නැටුම් කෝරසය", "වන්දනා නඩ එකිනෙකා හමු වූ විට පවා 'සමන් දෙවිඳු කරුණාවයි' යනුවෙන් සුබ පතා ගනිති."),
        q("ගොවි ජනතාව 'අඬහැර පෑම' (අඬහැරය) යනුවෙන් හඳුන්වනු ලබන්නේ කුමන ජන ගායන විලාසයද?", "සීසෑමේදී ගොනුන් මෙහෙයවමින් නගන දිගු හඬ ගීය", "පන්සලේ හේවිසි පූජා වාදනය කිරීම", "රබාන වටා හිඳ රබන් පද ගැයීම", "නාඩගම් වේදිකාවේ පොතේගුරු ගීතය", "කුඹුරේ මඩ සීසාන ගොවියා ගවයන් දිරිමත් කිරීමට හා තනිකම මකා ගැනීමට අඬහැර පායි."),
        q("'අඬහැර ගීත' ගායනා කිරීමේදී ඒවායේ රිද්මය හා හඬ පිහිටන්නේ කෙසේද?", "විවෘත උස් හඬින් ආරම්භ වී කෙළවර දීර්ඝ ස්වර ඇදීමකින් නිමවීම", "ඉතා සෙමින් කොඳුරා ගැයීම", "මද්දල තාලයට පමණක් ගැයීම", "වචන කිසිවක් නොකියා අත්පොළසන් දීම", "ඈත වෙල් යාය පුරා රැව් දෙන ලෙස ගොවියෝ විවෘත හඬින් අඬහැර ගයති."),
        q("ශ්‍රී ලංකාවේ 'උතුරු හා නැගෙනහිර' ප්‍රදේශවල දෙමළ ජන සංගීතයේ ප්‍රකට සාමූහික ජන ගී කාණ්ඩයක් වන්නේ කුමක්ද?", "නාට්ටුප්පුර පාඩල් ගී කාණ්ඩය", "උඩරට දහඅට වන්නම් පෙළ", "පහතරට සන්නි යකුම් කවි", "සබරගමු සොකරි කවි පෙළ", "දෙමළ ගැමි ධීවර, ගොවි හා කෝවිල් උත්සව හා බැඳුණු නාට්ටුප්පුර ගීත මෙරට ජන සංගීතයේ කොටසකි."),
        q("'කාවඩි සින්දු' ගායනය හා වාදනය ශ්‍රී ලංකාවේ කුමන ආගමික හා සංස්කෘතික උත්සව හා බැඳී ඇත්ද?", "කතරගම හා මුරුගන් (ස්කන්ධ) දේවාල උත්සව", "සිංහල අවුරුදු රබන් උත්සව", "බටහිර නත්තල් කැරොල්", "පැල් රැකීමේ උත්සව", "හින්දු හා බෞද්ධ බැතිමතුන් කතරගම පෙරහැරේදී කාවඩි කරමත තබාගෙන තාලයට ගයා නටති."),
        q("කාවඩි නර්තනයේදී බහුලව යොදාගනු ලබන සාම්ප්‍රදායික වාද්‍ය භාණ්ඩ යුගලය කුමක්ද?", "තවිල් බෙරය සහ නාදස්වරම් (හෝ තාලම්පට/හොරණෑව)", "පියානෝව සහ චෙලෝව", "සිතාරය සහ සන්තූරය", "ගිටාරය සහ සැක්සෆෝනය", "දකුණු ඉන්දීය ආභාසිත තවිල් බෙරය හා නාදස්වරම් කාවඩි රිද්මය තීව්‍ර කරයි."),
        q("ශ්‍රී ලංකාවේ 'බයිලා' සංගීතයේ මුල් අවස්ථාව වන 'වාද බයිලා' (Vada Baila) වල ප්‍රධාන ලක්ෂණය කුමක්ද?", "දෙපිරිසක් ප්‍රශ්න හා පිළිතුරු කවියෙන් ගයා විවාද කිරීම", "තනිව නිහඬව වයලීනය වාදනය කිරීම", "බෞද්ධ ආගමික ගාථා පමණක් සජ්ඣායනය", "වචන කිසිවක් නොමැතිව නර්තනය කිරීම", "අවස්ථානුකූලව පද ගොතා විවාද කිරීමේ සාම්ප්‍රදායික කලාවක් ලෙස වාද බයිලා පැවතුණි."),
        q("'ලයි ලයි ලා' හෝ 'තනන තනම්දන' වැනි අනුප්‍රාස පද ජන ගීයේදී හඳුන්වනු ලබන්නේ කුමන නමින්ද?", "තානම් පද හෝ ආලපන පද", "රාග පකඩ", "තාල විභාග", "විකෘති ස්වර", "කවියේ නාද මාලාවට ප්‍රවේශ වීමට හෝ ලය රැකීමට මෙම නිර්වචන රහිත තානම් පද යොදයි."),
        q("ගොයම් නෙළන කාන්තාවන් 'තන තන තම්දෙනා' කියා නෙළුම් කවි ඇරඹීමෙන් සිදුවන්නේ කුමක්ද?", "සියලු දෙනාම එකම ස්වර මට්ටමකට හා ලයකට එක්රැස් වීම", "කවිය අවසන් කිරීම", "බෙර වාදනය නතර කිරීම", "නින්දට යෑම", "සමූහ ගායනයකදී එකම ස්වරය හා තාලය සකස් කර ගැනීමට මුලින් තානම ගැයේ."),
        q("'පැදුරේ ඉඳගෙන' හෝ 'ගමේ කෝපි කඩේ' පරිසරයේ සැහැල්ලුවෙන් ගැයෙන ගීතවලට පොදුවේ ලැබෙන නම කුමක්ද?", "ගැමි සාජ්ජ / ජන ගී පැදුරු", "ශාස්ත්‍රීය ධ්‍රැපද් සභා", "ප්‍රොසීනියම් ඔපෙරා", "රාජකීය පෙරහැර", "ගමේ සමාජ රැස්වීම්වලදී අත් රබන් හා ඩෝල්කි සමඟ පැවැත්වූ ගී හමු ජන සංගීතය රැකගත්තේය."),
        q("දේශීය ජන ගී ගායනා අතර 'මල්වර ගී' හා 'රෙදි නැන්දාගේ කවි' වැනි චාරිත්‍ර ගී අයත් වන්නේ කුමන කාණ්ඩයටද?", "ගෘහස්ථ චාරිත්‍ර හා සමාජ ජන ගී", "මුහුදු ධීවර කාර්මික ජන ගී", "රාජ සභා යුද පෙළපාලි කවි", "සිනමා පසුබිම් තේමා ගීත", "ගැමි පවුල් ජීවිතයේ වැදගත් සන්ධිස්ථාන හා චාරිත්‍ර සමඟ බැඳුණු ගීත මේ ගණයට අයත් වේ."),
        q("විවාහ චාරිත්‍රවලදී 'පෝරුවේ චාරිත්‍ර' ඉටු කරන අතරතුර ගයනු ලබන සාම්ප්‍රදායික ගායනා මොනවාද?", "මංගල අෂ්ටක සහ ජයමංගල ගාථා", "පැල් කවි සහ පතල් කවි", "කපිරිඤ්ඤා බයිලා", "නාඩගම් කෝනංගි කවි", "නව යුවළට දීර්ඝායුෂ හා සෞභාග්‍යය පතා අෂ්ටක හා ජයමංගල ගාථා සම්ප්‍රදායිකව ගැයේ."),
        q("මංගල අවස්ථාවකදී 'මඟුල් බෙර' වාදනය කිරීමෙන් සංකේතවත් වන්නේ කුමක්ද?", "සියලු අසුබ දුරු කොට සුබ මංගල්‍යය ආරම්භ කිරීම", "විවාහය නතර කිරීම", "පතල් කැණීම ඇරඹීම", "ශෝකය ප්‍රකාශ කිරීම", "පූජනීය හා සුබ කටයුතුවල ආරම්භය මඟුල් බෙර හා හක්ගෙඩි නාදයෙන් ප්‍රකාශ වේ."),
        q("සිංහල ජන කවි අතර 'හෙළ ගැමි කාන්තාවගේ දුක හා වේදනාව' ඉතා සංවේදීව ප්‍රකාශ වන කවි විශේෂයක් වන්නේ කුමක්ද?", "වියෝග හා දුක්ඛ කවි (උදා පැල් හා නෙළුම් කවි තුළින්)", "රබන් නැටුම් පද පමණක්", "කපිරිඤ්ඤා ගීත", "රජුන් වර්ණනා කරන ප්‍රශස්ති", "දීග ගිය දියණියන් මව්පියන් සිහිකරමින් නෙළුම් හා කුරහන් කවිවලින් තම දුක ගැයූහ."),
        q("'පිටදීපේ දෙවියන්ට පින් දෙමු' වැනි පද්‍යවලින් පිළිබිඹු වන ජන ගීයේ ගුණාංගය කුමක්ද?", "කෘතඥතාපූර්වක බව හා ආගමික ශ්‍රද්ධාව", "ආත්මාර්ථකාමී බව", "අධික කෝපය", "නාගරික තරඟකාරීත්වය", "කරදරයකින් මිදුණු විට හෝ අස්වැන්න නෙළූ විට දෙවියන්ට පින් දීම ගැමියන්ගේ සිරිත විය."),
        q("පාරු කවි හා කරත්ත කවි ගායනයේදී 'තාල වාද්‍ය භාණ්ඩයක්' භාවිත නොකළද කවිය තුළ රිද්මයක් පවතින්නේ කෙසේද?", "වචන උච්චාරණයේ පවතින ඡන්දස් මාත්‍රා හා කටහඬේ විරාම නිසා", "ගසකට ගල් ගැසීම නිසා", "බටනළාවක් පිඹීම නිසා", "හාමෝනියමය වැයීම නිසා", "කවියේ පාද හතරේ මාත්‍රා බෙදීම ස්වාභාවික රිද්මයක් ලබාදේ."),
        q("සිංහල ජන සංගීතයේ 'මැදුම් දෙතිත' හා 'සුළු දෙතිත' භාවිත වන ප්‍රධාන ස්ථානය කුමක්ද?", "වන්නම් හා දේශීය බෙර වාදන තාලවල", "හින්දුස්ථානි ඛ්‍යාල්වල", "බටහිර සිම්ෆනිවල", "චීන ඔපෙරාවල", "දේශීය නැටුම්, වන්නම් හා හේවිසි තාල පදනම් වන්නේ තිත් ක්‍රම මතය."),
        q("පැරණි ශ්‍රී ලාංකිකයන් අතර 'පතල් කවි' වලින් කියැවෙන 'දබරේ' හා 'කූඩේ' යනු කුමක්ද?", "පතලේ පස් හා ඉල්ලම් උඩට අදින උපකරණ", "සංගීත භාණ්ඩ දෙකක්", "නැටුම් ඇඳුම් දෙකක්", "වී වර්ග දෙකක්", "පතල් කර්මාන්තයේ යෙදෙන වචන ජන කවිය තුළින් ඓතිහාසික සාක්ෂි සපයයි."),
        q("දේශීය ජන සංගීතයේදී 'තාල පද' (බෙර පද) මුඛයෙන් උච්චාරණය කිරීම හඳුන්වන්නේ කෙසේද?", "ශුද්ධ පද හෝ බෙර අක්ෂර", "සර්ගම් ස්වර තාන", "බටහිර සොල්ෆා ස්වර", "නත්තල් කැරොල් පද", "ගුරුවරයාගෙන් ශිෂ්‍යයාට බෙර වාදනය ඉගැන්වීමේදී මුලින්ම මුඛයෙන් බෙර පද පුහුණු කෙරේ."),
        q("'කුණ්ඩලකේශී' හෝ 'සඳකිඳුරු' කතා ඇසුරින් ගැමියන් ගැයූ ගීත හඳුන්වන්නේ කුමන පොදු නමකින්ද?", "ජනකතා හා ජාතක කවි ගායනා", "පෘතුගීසි බයිලා", "හින්දි චිත්‍රපට ගී", "මෝගල් ධ්‍රැපද්", "ධර්මදේශනා හා කාව්‍ය ගායනා ඇසුරින් ජාතක කතා ගැමි පිරිස අතර ප්‍රචලිත විය."),
        q("පහතරට 'දහඅට සන්නිය' වැනි ශාන්තිකර්මවලදී 'යක්බෙරය' සමඟ නටන නැට්ටුවන්ගේ හැඟීම් ප්‍රකාශනය සඳහා යොදාගන්නේ කුමක්ද?", "වෙස්මුහුණු, නැටුම් සහ යාතුකර්ම කවි ගායනය", "පියානෝ වාදනය", "හාමෝනියම් වාදනය", "ග්‍රැමෆෝන් තැටි", "රෝග නිවාරණය උදෙසා සන්නි යකුමේදී සන්නි කවි ගයමින් වෙස්මුහුණු පැළඳ රංගනය කෙරේ."),
        q("උඩරට 'සවරම්' හා 'උඩැක්කි' නැටුම්වලට ගායනා කරන කවිවල බහුලව අඩංගු වන්නේ කුමන තේමාවන්ද?", "දළදා වන්දනාව, බුදු ගුණ සහ ස්වභාවධර්ම වර්ණනා", "වෙළඳ දැන්වීම්", "විදේශීය දේශපාලනය", "ඉංග්‍රීසි පද්‍ය", "උඩරට නැටුම් සාම්ප්‍රදායිකව බෞද්ධ භක්තිය හා සංස්කෘතික අගයන් සමඟ බැඳී ඇත."),
        q("ගැමි සංගීතයේ එන 'දික් කවි' සහ 'කොට කවි' වෙනස් වන්නේ කවර සාධකයක් මතද?", "පේළියක ඇති මාත්‍රා හා අකුරු සංඛ්‍යාව අනුව", "බෙරයේ විෂ්කම්භය අනුව", "ගායකයාගේ උස අනුව", "ප්‍රේක්ෂකයන් ගණන අනුව", "සිව්පද කවියේ පාදයක ඇති මාත්‍රා ප්‍රමාණය අනුව ගායනා කාලය හා විරිත වෙනස් වේ."),
        q("වත්මන් සිංහල සරල ගීතයට 'බඹර නාද' හෝ 'පැල් කවි' ආභාසය ගෙන ගීත නිර්මාණය කිරීමෙන් සිදුවූ යහපත කුමක්ද?", "දේශීය හුරුවක් ඇති අනන්‍ය ශ්‍රී ලාංකේය ගීත කලාවක් බිහිවීම", "ජන ගී සම්පූර්ණයෙන් අමතක වීම", "සංගීත භාණ්ඩ භාවිතය නැවතීම", "විදේශීය භාෂා පමණක් ගැයීම", "අමරදේව, සුනිල් ශාන්ත, රෝහණ බැද්දගේ ආදීන් ජන ගී පදනම මත උසස් සරල ගී නිමවූහ."),
        q("සිංහල ජන කවි ගායනයේදී 'තාලයකට' නොබැඳී හුස්ම අනුව නිදහසේ ගැයෙන රීතිය හඳුන්වන්නේ කෙසේද?", "අනිබද්ධ (නිදහස්) ගැමි ගායන රීතිය", "ත්‍රිතාල බන්දිශ් රීතිය", "චෞතාල ධ්‍රැපද් රීතිය", "මාර්ච් රිද්ම රීතිය", "පැල් හා පාරු කවි බෙර තාලයකට යටත් නොවී හුස්ම පාලනය අනුව නිදහසේ ගැයේ."),
        q("'නිබද්ධ' ජන සංගීත අංගයන් සඳහා වඩාත් නිවැරදි උදාහරණ යුගලය කුමක්ද?", "රබන් පද සහ ලී කෙළි ගී", "පැල් කවි සහ පාරු කවි", "බම්බර කවි සහ අඬහැර", "තනිකම මකන කරත්ත කවි", "තාලයට හා ස්ථිර රිද්මයකට බැඳී නටමින් ගයන රබන්, ලී කෙළි හා කළගෙඩි ගී නිබද්ධ ගණයට වැටේ."),
        q("ලංකාවේ 'ගැමි කාන්තාවන්ගේ ශ්‍රමය' සමඟ බැඳී ඇති ප්‍රධාන ජන ගී වර්ග තුනක් නම් කරන්න.", "නෙළුම් කවි, කුරහන් කවි සහ කුලු කවි", "කරත්ත, පාරු සහ බම්බර කවි", "පතල්, අඬහැර සහ හටන් කවි", "නාඩගම්, නූර්ති සහ ටීටර්", "වී පැළ සිටුවීම, කුරහන් ඇඹරීම සහ වී පෙළීමේදී ගැමි කතුන් මෙම කවි ගැයූහ."),
        q("ගැමි කුඩා දරුවන් වෙනුවෙන් ගැයෙන 'අත්තම්මා' හෝ 'මව' ගයන දරු නැළවිලිවල අරමුණ කුමක්ද?", "දරුවා සනසා නින්දට පත් කරමින් මානසික බැඳීම වැඩි කිරීම", "දරුවා බිය ගැන්වීම", "ළමුන්ට තාල 16 ඉගැන්වීම", "ගෙදර වැඩ නතර කිරීම", "මෘදු ස්වර හා පුනරුච්චාරණ වචන මගින් දරුවාට ආරක්ෂාව හා සැනසීම දැනේ."),
        q("'කපිරිඤ්ඤා' ගීත හා දේශීය 'රබන් පද' අතර ඇති පොදු ලක්ෂණය කුමක්ද?", "සාමූහික විනෝදාස්වාදය හා ප්‍රීතිමත් නර්තන රිද්මය", "ගැඹුරු ශෝකී කරුණ රසය", "වනාන්තරයේ පැල් රැකීම", "තනිවම නිහඬව භාවනා කිරීම", "උත්සව හා සතුටුදායක අවස්ථාවලදී පිරිසක් එක්ව නටමින් ගැයීමට මේවා යොදාගනී."),
        q("'වන්නම්' ගායනා කිරීමේදී හඬ පුහුණු වීමට පෙර ශිෂ්‍යයන් ප්‍රගුණ කරන මූලික අංගය කුමක්ද?", "තාලය හා පාද චලන අනුව නිවැරදිව තානම ගායනා කිරීම", "තබ්ලාවේ සියාහි ගෑම", "බටහිර සොප්‍රානෝ ගායනය", "ගිටාරයේ කෝඩ්ස් ඇල්ලීම", "වන්නමේ ජීවය හා රිද්මය රඳා පවතින්නේ නිවැරදිව තානම ගායනා කිරීම මතය."),
        q("ගැමි පරිසරයේ 'මඩු ශාන්තිකර්මයකදී' ගැයෙන කවි වෙනස් වන්නේ කුමන අරමුණක් නිසාද?", "රෝග සුවය, අස්වනු සෞභාග්‍යය හා ගමට ආරක්ෂාව පැතීම", "මැණික් පතල් හෑරීම", "පාරු පැදීම", "නූර්ති ශාලා ප්‍රවර්ධනය", "ශාන්තිකර්ම සංගීතය සැමවිටම ආගමික හා සාමූහික සුවසෙත අරමුණු කරගනී."),
        q("ශ්‍රී ලංකාවේ 'ජන සංගීත පර්යේෂණ' සිදු කිරීමේදී වර්තමානයේ විශ්වවිද්‍යාල සිසුන් අනුගමනය කරන නිවැරදි ක්‍රමය කුමක්ද?", "ගම්මානවලට ගොස් පැරණි ගැමි ශිල්පීන් හමුවී පටිගත කර ස්වරලිපිගත කිරීම", "අනුමානයෙන් ගීත අලුතින් ලියා පැරණි බව පැවසීම", "විදේශීය පොත් පමණක් පරිවර්තනය කිරීම", "වාද්‍ය භාණ්ඩ කෞතුකාගාරයේ සඟවා තැබීම", "ක්ෂේත්‍ර අධ්‍යයනය (Field Research) මගින් සැබෑ ගැමි නාද රටා නිවැරදිව සංරක්ෂණය කළ හැකිය."),
        q("සිංහල ජන කවි හා ජන ගී සමුදාය හැදෑරීමෙන් සංගීත ශිෂ්‍යයෙකු තුළ ඇතිවන වඩාත් වැදගත් ආකල්පය කුමක්ද?", "තම මව්බිමේ සංස්කෘතික උරුමය කෙරෙහි ආදරය හා අභිමානය", "ජන කවි නොවැදගත් යැයි සිතීම", "සංගීත භාණ්ඩ අත්හැරීම", "ඉංග්‍රීසි ගීත පමණක් ප්‍රිය කිරීම", "අපේ පැරැන්නන්ගේ කලාත්මක නිර්මාණශීලීත්වය හා ජීවන අත්දැකීම් අගය කිරීමට ඉන් ඉඩ සැලසේ."),
        q("සිංහල ජන ගීය පිළිබඳව අවසන් නිගමනයක් ලෙස ගත් කල එය කෙබඳු කලා මාධ්‍යයක්ද?", "ශ්‍රමය, සොබාදහම, භක්තිය හා සතුට එක් කළ සජීවී සාමූහික කලා උරුමයකි", "විනෝදයට පමණක් නගරයේ නිර්මාණය වූවකි", "රජ සභාවලට පමණක් සීමා වූවකි", "විදේශිකයන් විසින් ලියන ලද පොතකි", "ශ්‍රී ලාංකික ගැමි සමාජයේ සැබෑ හදගැස්ම රැඳි අමිල සංස්කෘතික උරුමය ජන ගීයයි.")
    )
}
